function getLocalDate(offsetDays = 0) {
  const d = new Date();
  d.setMinutes(d.getMinutes() - d.getTimezoneOffset());
  d.setDate(d.getDate() + offsetDays);
  return d.toISOString().split('T')[0]; // "YYYY-MM-DD"
}

